-- =========================================================
-- DEMO: JADWAL RUANG RAPAT BIRO UMUM 2026
-- Bisa langsung dicoba di PostgreSQL 13+ mana pun (database kosong juga bisa):
--   createdb demo_ruang_rapat
--   psql -d demo_ruang_rapat -f demo_ruang_rapat_2026.sql
-- Kalau dijalankan di database aplikasi Biro Umum, tabelnya sudah ada sehingga
-- CREATE TABLE dilewati dan data langsung masuk ke tabel aplikasi.
-- =========================================================
-- Sumber : dok/Daftar peminjaman ruang rapat 2026 - REKAP.pdf (437 baris, 2026-01-05 s/d 2026-10-01).
-- Isi    : SERBAGUNA 51, SETJEN II 171, TRI DHARMA 96, BIRO UMUM 118, GRAHA KEMNAKER 1 booking.
--
-- Aturan konversi (PDF tidak punya kolom jam/PIC/HP terpisah):
--   * Agenda      = teks kolom "Pengguna" apa adanya.
--   * Jam         = dibaca dari teks ("jam 9 s.d. 12", "13.00 s/d selesai", "08-16", ...).
--                   "selesai"/tanpa jam selesai -> 16:00. Tidak ada jam sama sekali -> 08:00-16:00
--                   (299 baris). Beberapa kegiatan dalam satu sel digabung jadi satu rentang.
--   * PIC         = nama setelah "PIC ..." atau di dalam kurung bersama nomor HP; kalau tidak ada,
--                   nama unit pengguna (mis. "UKPBJ", "TU Biro Umum").
--   * No. HP PIC  = nomor HP yang tertulis di teks (36 baris); kalau tidak ada diisi '-'
--                   (lengkapi saat edit booking di aplikasi -- form edit mewajibkan No. HP valid).
--   * Nomor surat = kolom "Nomor Surat" (142 baris). File surat belum ada, jadi status surat
--                   = 'belum' (merah); upload suratnya lewat tab Surat di aplikasi.
--   * Ruangan "TrI DHARMA"/"TRIDHARMA" -> TRI DHARMA, "GRHA KEMNAKER" -> GRAHA KEMNAKER.
--   * 2 pasang booking di ruangan & tanggal yang sama jamnya beririsan (data asli memang
--     dobel / jamnya tidak tertulis). Impor tetap menyimpannya apa adanya; cek di kalender aplikasi.

-- Struktur tabel sama dengan tabel ruang_rapat di aplikasi (backend/prisma/schema.prisma),
-- tanpa foreign key ke tabel users supaya bisa berdiri sendiri.
CREATE TABLE IF NOT EXISTS ruang_rapat (
  id              SERIAL PRIMARY KEY,
  agenda          VARCHAR(255) NOT NULL,
  room            VARCHAR(150) NOT NULL,
  pic             VARCHAR(150) NOT NULL,
  pic_phone       VARCHAR(30)  NOT NULL,
  booking_date    DATE NOT NULL,
  end_date        DATE NOT NULL,
  start_time      TIME(0) NOT NULL,
  end_time        TIME(0) NOT NULL,
  surat_status    VARCHAR(20) NOT NULL DEFAULT 'belum' CHECK (surat_status IN ('belum','ditinjau','diterima')),
  nomor_surat     VARCHAR(100),
  surat_name      VARCHAR(255),
  surat_file_data TEXT,
  surat_file_path TEXT,
  created_by      INTEGER,
  updated_by      INTEGER,
  cancelled_at    TIMESTAMP(3),
  cancelled_by    INTEGER,
  cancel_reason   VARCHAR(500),
  booking_group   VARCHAR(36),
  created_at      TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CHECK (end_time > start_time),
  CHECK (end_date >= booking_date)
);
CREATE INDEX IF NOT EXISTS ruang_rapat_room_booking_date_end_date_idx ON ruang_rapat (room, booking_date, end_date);

BEGIN;

-- Kolom: tanggal, ruangan, agenda (isi kolom "Pengguna" apa adanya), nama PIC, no. HP PIC, nomor surat, jam mulai, jam selesai.
INSERT INTO ruang_rapat
  (agenda, room, pic, pic_phone, booking_date, end_date, start_time, end_time,
   surat_status, nomor_surat, booking_group, created_at, updated_at)
SELECT v.agenda, v.room, v.pic, v.pic_phone, v.tgl::date, v.tgl::date, v.mulai::time, v.selesai::time,
       'belum', v.nomor_surat, gen_random_uuid()::text,
       -- Jam UTC: kolom tanpa zona waktu dibaca aplikasi sebagai UTC (NOW() biasa = jam lokal server).
       now() AT TIME ZONE 'UTC', now() AT TIME ZONE 'UTC'
FROM (VALUES
