) AS v (tgl, room, agenda, pic, pic_phone, nomor_surat, mulai, selesai)
-- Aman dijalankan ulang: baris yang sudah pernah diimpor (tanggal + ruangan + agenda + jam mulai sama) dilewati.
WHERE NOT EXISTS (
  SELECT 1 FROM ruang_rapat r
  WHERE r.booking_date = v.tgl::date AND r.room = v.room AND r.agenda = v.agenda AND r.start_time = v.mulai::time
);

COMMIT;

-- Cek hasil: jumlah booking hasil impor per bulan & ruangan.
SELECT to_char(booking_date, 'YYYY-MM') AS bulan, room, COUNT(*) AS jumlah
FROM ruang_rapat
WHERE booking_date BETWEEN '2026-01-05' AND '2026-10-01' AND cancelled_at IS NULL
GROUP BY 1, 2
ORDER BY 1, 2;

-- Contoh query lain untuk dicoba:

-- 1. Jadwal satu hari (urut ruangan & jam).
SELECT room, to_char(start_time, 'HH24:MI') || '-' || to_char(end_time, 'HH24:MI') AS jam, agenda, pic, nomor_surat
FROM ruang_rapat
WHERE booking_date = '2026-07-22' AND cancelled_at IS NULL
ORDER BY room, start_time;

-- 2. Ruangan paling sering dipakai.
SELECT room, COUNT(*) AS jumlah_booking
FROM ruang_rapat
WHERE cancelled_at IS NULL
GROUP BY room
ORDER BY jumlah_booking DESC;

-- 3. Booking yang jamnya bentrok di ruangan & tanggal yang sama (aturan yang sama dengan cek bentrok aplikasi).
SELECT a.booking_date, a.room,
       a.agenda AS booking_1, to_char(a.start_time, 'HH24:MI') || '-' || to_char(a.end_time, 'HH24:MI') AS jam_1,
       b.agenda AS booking_2, to_char(b.start_time, 'HH24:MI') || '-' || to_char(b.end_time, 'HH24:MI') AS jam_2
FROM ruang_rapat a
JOIN ruang_rapat b ON a.id < b.id AND a.room = b.room
 AND a.booking_date <= b.end_date AND b.booking_date <= a.end_date
 AND a.start_time < b.end_time AND b.start_time < a.end_time
WHERE a.cancelled_at IS NULL AND b.cancelled_at IS NULL
ORDER BY a.booking_date, a.room;

-- 4. Booking yang sudah punya nomor surat tapi file suratnya belum diupload.
SELECT booking_date, room, agenda, nomor_surat
FROM ruang_rapat
WHERE nomor_surat IS NOT NULL AND surat_status = 'belum' AND cancelled_at IS NULL
ORDER BY booking_date;
